//! Triton-compiled DXIL kernel dispatch for Moonshine encoder on D3D12.
//!
//! Pre-compiled DXIL bytecode (generated by Triton AOT → HLSL → DXC).
//! All kernels use RWStructuredBuffer<half> for buffer args (SM 6.2+ native half)
//! and cbuffer root constants for scalar args + grid dimensions.

use anyhow::Result;
use candle_d3d12_kernels::{BufferBinding, Gpu, GpuBuffer, ID3D12PipelineState};
use std::sync::Arc;

fn cdiv(a: usize, b: usize) -> usize {
    (a + b - 1) / b
}

// Auto-generated: DXIL constants, TritonD3D12Kernels struct + load(),
// D3D12DecoderKernels struct + load().
include!("../kernels/out/generated/triton_d3d12_gen.rs");

impl TritonD3D12Kernels {

    /// Select the best matmul PSO based on block size and fp16_acc preference.
    fn select_matmul_pso(&self, block_m: usize) -> &ID3D12PipelineState {
        if self.prefer_fp16_acc {
            if let Some(ref pso) = self.matmul_acc16_64x64 {
                return pso;
            }
        }
        if block_m >= 128 {
            self.matmul_128x128.as_ref().unwrap_or(&self.matmul_64x64)
        } else {
            &self.matmul_64x64
        }
    }

    /// Select the best matmul+bias PSO based on fp16_acc preference.
    fn select_matmul_bias_pso(&self) -> &ID3D12PipelineState {
        if self.prefer_fp16_acc {
            if let Some(ref pso) = self.matmul_bias_acc16_32x32 {
                return pso;
            }
        }
        &self.matmul_bias_32x32
    }
}

// ── Helper: pack i32 as u32 root constant ──

fn i32_as_u32(v: i32) -> u32 {
    v as u32
}

// ── Buffer management ──

/// Create a GPU buffer for `count` half-precision elements.
pub fn create_f16_buffer(gpu: &Gpu, count: usize) -> Result<GpuBuffer> {
    let size_bytes = (count * 2) as u64; // half = 2 bytes
    gpu.create_buffer(size_bytes)
        .map_err(|e| anyhow::anyhow!("create_buffer: {e}"))
}

/// Upload F16 data (as raw bytes) to a GPU buffer.
pub fn upload_f16(gpu: &Gpu, data: &[u8], dst: &GpuBuffer) -> Result<()> {
    gpu.upload_to_buffer(data, dst)
        .map_err(|e| anyhow::anyhow!("upload: {e}"))
}

/// Download GPU buffer to F16 bytes.
pub fn download_f16(gpu: &Gpu, src: &GpuBuffer, count: usize) -> Result<Vec<u8>> {
    let size_bytes = (count * 2) as u64;
    gpu.download_buffer(src, size_bytes)
        .map_err(|e| anyhow::anyhow!("download: {e}"))
}

/// Bind a buffer as RWStructuredBuffer<half> UAV.
fn uav_f16<'a>(buf: &'a GpuBuffer, count: u32) -> BufferBinding<'a> {
    BufferBinding::structured_f16(buf, count)
}

/// Bind a buffer as RWStructuredBuffer<float> UAV.
fn uav_f32<'a>(buf: &'a GpuBuffer, count: u32) -> BufferBinding<'a> {
    BufferBinding::structured_f32(buf, count)
}

/// Create a GPU buffer for `count` float32 elements.
pub fn create_f32_buffer(gpu: &Gpu, count: usize) -> Result<GpuBuffer> {
    let size_bytes = (count * 4) as u64;
    gpu.create_buffer(size_bytes)
        .map_err(|e| anyhow::anyhow!("create_f32_buffer: {e}"))
}

/// Upload F32 data (as raw bytes) to a GPU buffer.
pub fn upload_f32(gpu: &Gpu, data: &[u8], dst: &GpuBuffer) -> Result<()> {
    gpu.upload_to_buffer(data, dst)
        .map_err(|e| anyhow::anyhow!("upload_f32: {e}"))
}

/// Download GPU buffer to F32 bytes.
pub fn download_f32(gpu: &Gpu, src: &GpuBuffer, count: usize) -> Result<Vec<u8>> {
    let size_bytes = (count * 4) as u64;
    gpu.download_buffer(src, size_bytes)
        .map_err(|e| anyhow::anyhow!("download_f32: {e}"))
}

// ── Dispatch functions ──

/// Dispatch matmul: C[M,N] = A[M,K] @ B[K,N] (all F16)
///
/// B must be [K, N] row-major (stride_bk=N, stride_bn=1).
/// Automatically selects fp16 or fp32 accumulation based on `prefer_fp16_acc`.
pub fn triton_d3d12_matmul(
    kernels: &TritonD3D12Kernels,
    a: &GpuBuffer,
    b: &GpuBuffer,
    out: &GpuBuffer,
    m: usize,
    n: usize,
    k: usize,
    block_m: usize,
    _block_n: usize,
) -> Result<()> {
    let pso = kernels.select_matmul_pso(block_m);

    // fp16 acc variants always use 64x64 tiles
    let (bm, bn) = if kernels.prefer_fp16_acc && kernels.matmul_acc16_64x64.is_some() {
        (64, 64)
    } else if block_m >= 128 && kernels.matmul_128x128.is_some() {
        (128, 128)
    } else {
        (64, 64)
    };

    let grid_x = cdiv(m, bm) as u32;
    let grid_y = cdiv(n, bn) as u32;

    // cbuffer layout: arg3..arg11 (9 scalars) + grid_dim_x/y/z (3)
    let root_constants: Vec<u32> = vec![
        i32_as_u32(m as i32),         // arg3: M
        i32_as_u32(n as i32),         // arg4: N
        i32_as_u32(k as i32),         // arg5: K
        i32_as_u32(k as i32),         // arg6: stride_am = K
        i32_as_u32(1),                // arg7: stride_ak = 1
        i32_as_u32(n as i32),         // arg8: stride_bk = N
        i32_as_u32(1),                // arg9: stride_bn = 1
        i32_as_u32(n as i32),         // arg10: stride_cm = N
        i32_as_u32(1),                // arg11: stride_cn = 1
        grid_x, grid_y, 1,           // grid dims
    ];

    let uavs = [
        uav_f16(a, (m * k) as u32),
        uav_f16(b, (k * n) as u32),
        uav_f16(out, (m * n) as u32),
    ];

    kernels.gpu.dispatch_uav_only(pso, &root_constants, &uavs, [grid_x, grid_y, 1])
        .map_err(|e| anyhow::anyhow!("matmul dispatch: {e}"))
}

/// Dispatch matmul + bias: C[M,N] = A[M,K] @ B[K,N] + bias[N] (all F16)
/// Automatically selects fp16 or fp32 accumulation based on `prefer_fp16_acc`.
pub fn triton_d3d12_matmul_bias(
    kernels: &TritonD3D12Kernels,
    a: &GpuBuffer,
    b: &GpuBuffer,
    bias: &GpuBuffer,
    out: &GpuBuffer,
    m: usize,
    n: usize,
    k: usize,
    _block_m: usize,
    _block_n: usize,
) -> Result<()> {
    let pso = kernels.select_matmul_bias_pso();
    let bm = 32;
    let bn = 32;

    let grid_x = cdiv(m, bm) as u32;
    let grid_y = cdiv(n, bn) as u32;

    // Pointer args: 0=a, 1=b, 2=bias, 3=c → 4 UAVs
    // Scalar args: 4=M,5=N,6=K,7=stride_am,...12=stride_cn → 9 scalars + 3 grid
    let root_constants: Vec<u32> = vec![
        i32_as_u32(m as i32),
        i32_as_u32(n as i32),
        i32_as_u32(k as i32),
        i32_as_u32(k as i32),         // stride_am = K
        i32_as_u32(1),                // stride_ak = 1
        i32_as_u32(n as i32),         // stride_bk = N
        i32_as_u32(1),                // stride_bn = 1
        i32_as_u32(n as i32),         // stride_cm = N
        i32_as_u32(1),                // stride_cn = 1
        grid_x, grid_y, 1,
    ];

    let uavs = [
        uav_f16(a, (m * k) as u32),
        uav_f16(b, (k * n) as u32),
        uav_f16(bias, n as u32),
        uav_f16(out, (m * n) as u32),
    ];

    kernels.gpu.dispatch_uav_only(pso, &root_constants, &uavs, [grid_x, grid_y, 1])
        .map_err(|e| anyhow::anyhow!("matmul_bias dispatch: {e}"))
}

/// Dispatch unit-offset layernorm: out = LN(x) * (gamma + 1.0) (F16)
///
/// Pointer args: 0=x, 1=gamma, 2=out
/// Scalar args: 3=n_rows, 4=n_cols, 5=stride_x_row, 6=stride_out_row
pub fn triton_d3d12_layernorm(
    kernels: &TritonD3D12Kernels,
    x: &GpuBuffer,
    gamma: &GpuBuffer,
    out: &GpuBuffer,
    n_rows: usize,
    n_cols: usize,
) -> Result<()> {
    let grid_x = n_rows as u32;

    let root_constants: Vec<u32> = vec![
        i32_as_u32(n_rows as i32),
        i32_as_u32(n_cols as i32),
        i32_as_u32(n_cols as i32),     // stride_x_row = n_cols (contiguous)
        i32_as_u32(n_cols as i32),     // stride_out_row = n_cols
        grid_x, 1, 1,
    ];

    let uavs = [
        uav_f16(x, (n_rows * n_cols) as u32),
        uav_f16(gamma, n_cols as u32),
        uav_f16(out, (n_rows * n_cols) as u32),
    ];

    kernels.gpu.dispatch_uav_only(&kernels.layernorm_unit_offset, &root_constants, &uavs, [grid_x, 1, 1])
        .map_err(|e| anyhow::anyhow!("layernorm dispatch: {e}"))
}

/// Dispatch GELU activation: out[i] = gelu(x[i]) (F16)
///
/// Pointer args: 0=x, 1=out
/// Scalar args: 2=n_elements
pub fn triton_d3d12_gelu(
    kernels: &TritonD3D12Kernels,
    x: &GpuBuffer,
    out: &GpuBuffer,
    n_elements: usize,
) -> Result<()> {
    let grid_x = cdiv(n_elements, 1024) as u32;

    let root_constants: Vec<u32> = vec![
        i32_as_u32(n_elements as i32),
        grid_x, 1, 1,
    ];

    let uavs = [
        uav_f16(x, n_elements as u32),
        uav_f16(out, n_elements as u32),
    ];

    kernels.gpu.dispatch_uav_only(&kernels.gelu, &root_constants, &uavs, [grid_x, 1, 1])
        .map_err(|e| anyhow::anyhow!("gelu dispatch: {e}"))
}

