/// Dispatch Flash Attention 2: O = softmax(Q @ K^T / sqrt(d)) @ V
///
/// Q, K, V, O: fp16 buffers with n_heads * seq_len * head_dim elements.
/// stride_h: element stride between heads (head_dim for interleaved, seq_len*head_dim for separated)
/// stride_m: element stride between sequence positions (kv_dim for interleaved, head_dim for separated)
/// Uses online softmax (Dao et al.) with sliding window masking.
/// Grid: (cdiv(seq_len, 32), n_heads, 1)
pub fn triton_d3d12_flash_attention(
    kernels: &TritonD3D12Kernels,
    q: &GpuBuffer,
    k: &GpuBuffer,
    v: &GpuBuffer,
    out: &GpuBuffer,
    n_heads: usize,
    padded_seq: usize,
    seq_len: usize,
    head_dim: usize,
    sm_scale: f32,
    window_left: i32,
    window_right: i32,
) -> Result<()> {
    let bm = 32;
    let grid_x = cdiv(padded_seq, bm) as u32;
    let grid_y = n_heads as u32;

    // Interleaved layout: Q/K/V are [padded_seq, n_heads * head_dim]
    // element(h, s, d) = h * head_dim + s * (n_heads * head_dim) + d
    let stride_h = head_dim as i32;
    let stride_m = (n_heads * head_dim) as i32;

    // cbuffer layout: arg4..arg10 (7 scalars) + grid_dim_x/y/z (3)
    // arg4 = seq_len (for masking), NOT padded_seq
    let stride_o = stride_m; // output has same layout as Q/K/V for encoder
    let root_constants: Vec<u32> = vec![
        i32_as_u32(seq_len as i32),       // arg4: seq_len (mask bound)
        i32_as_u32(stride_h),             // arg5: stride_h
        i32_as_u32(stride_m),             // arg6: stride_qkv
        i32_as_u32(stride_o),             // arg7: stride_o
        sm_scale.to_bits(),               // arg8: sm_scale (as float bits)
        i32_as_u32(window_left),          // arg9: window_left
        i32_as_u32(window_right),         // arg10: window_right
        grid_x, grid_y, 1,               // grid dims
    ];

    let n_elem = (n_heads * padded_seq * head_dim) as u32;
    let uavs = [
        uav_f16(q, n_elem),
        uav_f16(k, n_elem),
        uav_f16(v, n_elem),
        uav_f16(out, n_elem),
    ];

    kernels.gpu.dispatch_uav_only(&kernels.flash_attn_d64, &root_constants, &uavs, [grid_x, grid_y, 1])
        .map_err(|e| anyhow::anyhow!("flash_attention dispatch: {e}"))
}

/// Dispatch softmax over rows: out[r,:] = softmax(x[r,:]) (F16)
///
/// Pointer args: 0=input, 1=output
/// Scalar args: 2=n_rows, 3=n_cols, 4=stride_row
pub fn triton_d3d12_softmax(
    kernels: &TritonD3D12Kernels,
    input: &GpuBuffer,
    output: &GpuBuffer,
    n_rows: usize,
    n_cols: usize,
) -> Result<()> {
    let grid_x = n_rows as u32;

    let root_constants: Vec<u32> = vec![
        i32_as_u32(n_rows as i32),
        i32_as_u32(n_cols as i32),
        i32_as_u32(n_cols as i32),     // stride_row = n_cols (contiguous)
        grid_x, 1, 1,
    ];

    let uavs = [
        uav_f16(input, (n_rows * n_cols) as u32),
        uav_f16(output, (n_rows * n_cols) as u32),
    ];

    kernels.gpu.dispatch_uav_only(&kernels.softmax, &root_constants, &uavs, [grid_x, 1, 1])
        .map_err(|e| anyhow::anyhow!("softmax dispatch: {e}"))
}
